const repo = String($env.DEPLOY_GUARD_REPO || 'ziemaziema-center/n8n-workflows').trim();
const branch = String($env.DEPLOY_GUARD_BRANCH || 'master').trim();
const allowedPrefix = 'workflows/live/';
const telegramChatId = String($env.DEPLOY_GUARD_TELEGRAM_CHAT_ID || '').trim();
const telegramTokenPresent = !!String($env.DEPLOY_GUARD_TELEGRAM_BOT_TOKEN || '').trim();
return [{ json: { repo, branch, allowed_prefix: allowedPrefix, telegram_chat_id_present: !!telegramChatId, telegram_token_present: telegramTokenPresent } }];

const commit = $json || {};
const sha = String(commit.sha || '').trim();
if (!sha) return [{ json: { should_continue: false, status: 'blocked', reason: 'missing_commit_sha' } }];
const store = $getWorkflowStaticData('global');
store.mobile_codex_deploy_guard = store.mobile_codex_deploy_guard && typeof store.mobile_codex_deploy_guard === 'object' ? store.mobile_codex_deploy_guard : {};
const state = store.mobile_codex_deploy_guard;
state.processed_commit_shas = Array.isArray(state.processed_commit_shas) ? state.processed_commit_shas : [];
const processed = state.lastProcessedCommit === sha || state.last_processed_commit === sha || state.processed_commit_shas.includes(sha) || state.pending_sha === sha || state.deployed_sha === sha;
if (processed) {
  return [{ json: { should_continue: false, status: 'skipped', reason: 'commit_already_processed', sha } }];
}
return [{ json: { should_continue: true, status: 'new_commit', sha, repo: String($env.DEPLOY_GUARD_REPO || 'ziemaziema-center/n8n-workflows'), branch: String($env.DEPLOY_GUARD_BRANCH || 'master') } }];

const commit = $json || {};
const sha = String(commit.sha || '').trim();
const files = Array.isArray(commit.files) ? commit.files : [];
const changed = files.map(f => ({ filename: String(f.filename || '').trim(), status: String(f.status || '').trim(), raw_url: String(f.raw_url || '').trim(), patch: String(f.patch || '') })).filter(f => f.filename);
const live = changed.filter(f => /^workflows\/live\/[^/]+\.json$/.test(f.filename));
const disallowed = changed.filter(f => !/^workflows\/live\/[^/]+\.json$/.test(f.filename));
const publisherFiles = live.filter(f => /clean_03_publisher\.json$|clean_04_carousel_publisher\.json$/.test(f.filename));
const reasons = [];
if (!changed.length) reasons.push('no_changed_files');
if (disallowed.length) reasons.push('non_live_workflow_files_changed');
if (live.length !== 1) reasons.push('v1_requires_exactly_one_live_workflow_file');
if (publisherFiles.length) reasons.push('publisher_workflows_blocked_in_v1');
const allowed = reasons.length === 0;
const target = live[0] || {};
return [{ json: { sha, allowed, reasons, changed_files: changed.map(f => f.filename), target_file: target.filename || '', target_raw_url: target.raw_url || '' } }];

const raw = typeof $json === 'string' ? $json : String($json.data || $json.body || JSON.stringify($json));
let parsed;
const reasons = [];
try { parsed = JSON.parse(raw); } catch (e) { reasons.push('invalid_json'); parsed = {}; }
if (!parsed.name || !Array.isArray(parsed.nodes) || !parsed.connections || typeof parsed.connections !== 'object') reasons.push('invalid_n8n_workflow_shape');
const text = raw;
const secretPatterns = [
  /xox[baprs]-[A-Za-z0-9-]+/,
  /gh[pousr]_[A-Za-z0-9_]{20,}/,
  /EAAC[A-Za-z0-9]{20,}/,
  /[0-9]{8,}:[A-Za-z0-9_-]{30,}/,
  /sk-[A-Za-z0-9_-]{20,}/,
  /access_token\s*[=:]\s*['\"][^'\"]+['\"]/i,
  /api[_-]?key\s*[=:]\s*['\"][^'\"]+['\"]/i
];
if (secretPatterns.some(rx => rx.test(text))) reasons.push('secret_like_pattern_found');
if (parsed.active === true) reasons.push('active_true_blocked_in_v1');
const ok = reasons.length === 0;
return [{ json: { safety_passed: ok, reasons, workflow_name: String(parsed.name || ''), node_count: Array.isArray(parsed.nodes) ? parsed.nodes.length : 0, sha: $node['Filter Allowed Workflow Changes'].json.sha, target_file: $node['Filter Allowed Workflow Changes'].json.target_file } }];

const j = $json || {};
const approvalId = `${j.sha}|${j.target_file}`;
const store = $getWorkflowStaticData('global');
store.mobile_codex_deploy_guard = store.mobile_codex_deploy_guard && typeof store.mobile_codex_deploy_guard === 'object' ? store.mobile_codex_deploy_guard : {};
store.mobile_codex_deploy_guard.pending_sha = j.sha;
store.mobile_codex_deploy_guard.pending_approval_id = approvalId;
store.mobile_codex_deploy_guard.pending_file = j.target_file;
store.mobile_codex_deploy_guard.pending_at = new Date().toISOString();
const text = [
  '[MOBILE CODEX DEPLOY GUARD]',
  'Approval required before any n8n deploy.',
  `commit: ${j.sha}`,
  `file: ${j.target_file}`,
  `workflow: ${j.workflow_name}`,
  `nodes: ${j.node_count}`,
  '',
  'V1 stops here after this Telegram request. No deploy runs from Cron.'
].join('\n');
const reply_markup = {
  inline_keyboard: [
    [{ text: 'Approve Deploy', callback_data: `approve_deploy|${approvalId}` }],
    [{ text: 'Reject', callback_data: `reject_deploy|${approvalId}` }]
  ]
};
return [{ json: { ...j, approval_id: approvalId, telegram_text: text, telegram_reply_markup: reply_markup } }];

const j = $json || {};
const text = [
  '[MOBILE CODEX DEPLOY GUARD BLOCKED]',
  `commit: ${j.sha || 'unknown'}`,
  `target: ${j.target_file || 'none'}`,
  `reasons: ${(j.reasons || []).join(', ') || 'unknown'}`,
  '',
  'No deployment attempted.'
].join('\n');
return [{ json: { ...j, telegram_text: text } }];

const input = $input.first()?.json || {};
const body = input.body && typeof input.body === 'object' ? input.body : input;
const callback = body.callback_query && typeof body.callback_query === 'object' ? body.callback_query : {};
const data = String(callback.data || body.data || '').trim();
const [action, approvalId] = data.split('|');
const store = $getWorkflowStaticData('global');
store.mobile_codex_deploy_guard = store.mobile_codex_deploy_guard && typeof store.mobile_codex_deploy_guard === 'object' ? store.mobile_codex_deploy_guard : {};
const state = store.mobile_codex_deploy_guard;
const valid = approvalId && approvalId === state.pending_approval_id;
state.last_callback_at = new Date().toISOString();
state.last_callback_action = action || '';
state.last_callback_valid = !!valid;
if (valid && action === 'reject_deploy') {
  state.rejected_sha = state.pending_sha;
  state.pending_sha = '';
  state.pending_approval_id = '';
}
if (valid && action === 'approve_deploy') {
  state.approved_sha = state.pending_sha;
  state.approved_file = state.pending_file;
  state.approved_at = new Date().toISOString();
}
return [{ json: { ok: true, deploy_triggered: false, approval_valid: !!valid, action: action || '', message: 'V1 records approval only. No n8n deployment node exists in this workflow.' } }];

const source = $node['Create Pending Approval'].json || {};
const sha = String(source.sha || '').trim();
if (!sha) throw new Error('Missing sha to mark processed after approval request');
const store = $getWorkflowStaticData('global');
store.mobile_codex_deploy_guard = store.mobile_codex_deploy_guard && typeof store.mobile_codex_deploy_guard === 'object' ? store.mobile_codex_deploy_guard : {};
const state = store.mobile_codex_deploy_guard;
state.processed_commit_shas = Array.isArray(state.processed_commit_shas) ? state.processed_commit_shas : [];
if (!state.processed_commit_shas.includes(sha)) state.processed_commit_shas.push(sha);
state.processed_commit_shas = state.processed_commit_shas.slice(-100);
state.lastProcessedCommit = sha;
state.last_processed_commit = sha;
state.last_processed_commit_at = new Date().toISOString();
state.last_processed_commit_result = 'approval_request_sent';
return [{ json: { commit_processed: true, result: 'approval_request_sent', sha } }];

const source = $node['Build Blocked Report'].json || {};
const sha = String(source.sha || '').trim();
if (!sha) throw new Error('Missing sha to mark processed after blocked report');
const store = $getWorkflowStaticData('global');
store.mobile_codex_deploy_guard = store.mobile_codex_deploy_guard && typeof store.mobile_codex_deploy_guard === 'object' ? store.mobile_codex_deploy_guard : {};
const state = store.mobile_codex_deploy_guard;
state.processed_commit_shas = Array.isArray(state.processed_commit_shas) ? state.processed_commit_shas : [];
if (!state.processed_commit_shas.includes(sha)) state.processed_commit_shas.push(sha);
state.processed_commit_shas = state.processed_commit_shas.slice(-100);
state.lastProcessedCommit = sha;
state.last_processed_commit = sha;
state.last_processed_commit_at = new Date().toISOString();
state.last_processed_commit_result = 'blocked_report_sent';
return [{ json: { commit_processed: true, result: 'blocked_report_sent', sha } }];
